package com.worldlag;

import java.awt.Color;
import java.awt.Font;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/** World Lag's options - here (the wrench) and in its side panel
 *  (WorldLagPanel), the same settings. */
@ConfigGroup(WorldLagConfig.GROUP)
public interface WorldLagConfig extends Config {
  String GROUP = "worldlag";

  enum TextFont {
    REGULAR("Regular"),
    BOLD("Bold"),
    SMALL("Small");

    private final String name;
    TextFont(String name) { this.name = name; }
    Font font() { return this == BOLD ? FontManager.getRunescapeBoldFont() : this == SMALL ? FontManager.getRunescapeSmallFont() : FontManager.getRunescapeFont(); }
    @Override public String toString() { return name; }
  }

  @ConfigSection(name = "The box", description = "How the input lag box looks", position = 0)
  String box = "box";
  @ConfigSection(name = "Colours", description = "The box's colours", position = 10)
  String colours = "colours";
  @ConfigSection(name = "Measuring", description = "What counts as good or bad, and over how long", position = 20)
  String measuring = "measuring";

  @ConfigItem(keyName = "showWorld", name = "Show the world", description = "A \"World 404\" line over the input lag. Off: one line.", section = box, position = 1)
  default boolean showWorld() { return true; }

  @ConfigItem(keyName = "font", name = "Font", description = "The box's font", section = box, position = 2)
  default TextFont font() { return TextFont.REGULAR; }

  @ConfigItem(keyName = "goodColor", name = "Good", description = "The number's colour when the input lag is good", section = colours, position = 11)
  default Color goodColor() { return new Color(0x0dc10d); }

  @ConfigItem(keyName = "okColor", name = "So-so", description = "The number's colour between good and bad", section = colours, position = 12)
  default Color okColor() { return new Color(0xffff00); }

  @ConfigItem(keyName = "badColor", name = "Bad", description = "The number's colour when the input lag is bad", section = colours, position = 13)
  default Color badColor() { return new Color(0xff3030); }

  @ConfigItem(keyName = "textColor", name = "Text", description = "The world and \"Input lag\"", section = colours, position = 14)
  default Color textColor() { return Color.WHITE; }

  @Alpha
  @ConfigItem(keyName = "backgroundColor", name = "Background", description = "The box's background", section = colours, position = 15)
  default Color backgroundColor() { return ComponentConstants.STANDARD_BACKGROUND_COLOR; }

  @ConfigItem(keyName = "goodMs", name = "Good up to", description = "Input lag up to this is good. A normal world measured 125-185 ms.", section = measuring, position = 21)
  @Range(min = 50, max = 600)
  @Units(Units.MILLISECONDS)
  default int goodMs() { return 190; }

  @ConfigItem(keyName = "badMs", name = "Bad above", description = "Input lag above this is bad. World 404 measured 225-285 ms.", section = measuring, position = 22)
  @Range(min = 50, max = 600)
  @Units(Units.MILLISECONDS)
  default int badMs() { return 220; }

  @ConfigItem(keyName = "minutes", name = "Measure over", description = "The input lag of this many minutes of play. Shorter reacts faster, longer is steadier.", section = measuring, position = 23)
  @Range(min = 2, max = 30)
  @Units(Units.MINUTES)
  default int minutes() { return 5; }
}

package com.worldlag;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * World Lag's box: the world and its input lag - how long before the next
 * tick a click has to go in to count (WorldLagStats.deadlineMs). Two lines
 * (kept small beside other info boxes), or one; the number's colour says
 * if it's good. Alt + drag moves it (any overlay's).
 */
class WorldLagOverlay extends OverlayPanel {
  private final WorldLagPlugin plugin;
  private final WorldLagConfig config;

  @Inject
  WorldLagOverlay(WorldLagPlugin plugin, WorldLagConfig config) {
    super(plugin);
    this.plugin = plugin;
    this.config = config;
    setPosition(OverlayPosition.TOP_LEFT);
  }

  /** The number's colour (gray: still measuring). */
  static Color shade(WorldLagConfig c, int lag) {
    return lag < 0 ? Color.GRAY : lag <= c.goodMs() ? c.goodColor() : lag <= c.badMs() ? c.okColor() : c.badColor();
  }

  @Override
  public Dimension render(Graphics2D g) {
    int lag = plugin.stats.deadlineMs();
    Font font = config.font().font();
    g.setFont(font);
    panelComponent.setBackgroundColor(config.backgroundColor());
    if (config.showWorld()) panelComponent.getChildren().add(TitleComponent.builder().text("World " + plugin.world()).color(config.textColor()).build());
    panelComponent.getChildren().add(LineComponent.builder()
        .left("Input lag").leftColor(config.textColor()).leftFont(font)
        .right(lag < 0 ? "measuring" : lag + " ms").rightColor(shade(config, lag)).rightFont(font).build());
    panelComponent.setPreferredSize(new Dimension(g.getFontMetrics(font).stringWidth("Input lag  measuring") + 12, 0));
    return super.render(g);
  }
}

package com.worldlag;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.Cursor;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

/**
 * World Lag's side panel: the input lag now and on the worlds you've been
 * on this session, what it is, and the box's options (the same settings as
 * the wrench's - either changes both).
 */
class WorldLagPanel extends PluginPanel {
  private static final String[] KEYS = {"showWorld", "font", "goodColor", "okColor", "badColor", "textColor", "backgroundColor", "goodMs", "badMs", "minutes"};

  private final WorldLagConfig config;
  private final ConfigManager configManager;
  private final ColorPickerManager pickers;

  private final JLabel world = new JLabel();
  private final JLabel lag = new JLabel();
  private final JLabel from = new JLabel();
  private final JPanel session = new Fit(new GridLayout(0, 2, 0, 2));
  private final JCheckBox showWorld = new JCheckBox("Show the world");
  private final JComboBox<WorldLagConfig.TextFont> font = new JComboBox<>(WorldLagConfig.TextFont.values());
  private final JSpinner goodMs = new JSpinner(new SpinnerNumberModel(190, 50, 600, 10));
  private final JSpinner badMs = new JSpinner(new SpinnerNumberModel(220, 50, 600, 10));
  private final JSpinner minutes = new JSpinner(new SpinnerNumberModel(5, 2, 30, 1));
  private final JLabel[] colours = new JLabel[5];
  /** (Setting the controls from the config: not a change of the user's.) */
  private boolean filling;
  /** The numbers as of the last tick (copied on the client's thread). */
  private int nowWorld = -1, nowLag = -1, nowClicks;
  private Map<Integer, Integer> nowSeen = new LinkedHashMap<>();

  WorldLagPanel(WorldLagConfig config, ConfigManager configManager, ColorPickerManager pickers) {
    this.config = config;
    this.configManager = configManager;
    this.pickers = pickers;
    setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
    setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

    // Now.
    JPanel now = card();
    world.setFont(FontManager.getRunescapeBoldFont());
    world.setForeground(ColorScheme.TEXT_COLOR);
    lag.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
    from.setFont(FontManager.getRunescapeSmallFont());
    from.setForeground(Color.GRAY);
    for (JLabel l : new JLabel[] {world, lag, from}) { l.setAlignmentX(Component.CENTER_ALIGNMENT); now.add(l); }
    add(heading("Input lag now"));
    add(fit(now));
    add(Box.createVerticalStrut(8));
    add(heading("This session"));
    session.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    session.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
    session.setAlignmentX(Component.LEFT_ALIGNMENT);
    add(fit(session));

    add(Box.createVerticalStrut(8));
    add(heading("What is input lag?"));
    add(text("The game runs in ticks, one every 0.6 seconds. A click only counts on the next tick if it gets to the server in time - too late and it waits a whole extra tick."));
    add(text("Input lag is how long before the next tick you have to click for it to count: your ping, plus how long the world's server takes to take your click in. Everything you do waits on it - prayers, switches, eating, moving."));
    add(text("Normal worlds measure about 125-185 ms. A busy world (404, at its worst) measured 225-285 ms: about a sixth of every tick gone."));
    add(text("It's measured from the prayer, gear and food clicks you already make - which tick each one's change came back on. It needs about 30 of them (a few minutes of fighting) before it shows a number."));

    add(Box.createVerticalStrut(8));
    add(heading("The box"));
    JPanel opts = new Fit(new GridBagLayout());
    opts.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    opts.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
    showWorld.setOpaque(false);
    showWorld.setForeground(ColorScheme.TEXT_COLOR);
    showWorld.addActionListener(e -> set("showWorld", showWorld.isSelected()));
    font.addActionListener(e -> set("font", font.getSelectedItem()));
    row(opts, null, showWorld);
    row(opts, "Font", font);
    font.setPreferredSize(new Dimension(92, 22));
    font.setMinimumSize(new Dimension(92, 22));
    String[] names = {"Good colour", "So-so colour", "Bad colour", "Text colour", "Background"};
    String[] keys = {"goodColor", "okColor", "badColor", "textColor", "backgroundColor"};
    for (int i = 0; i < 5; i++) {
      final String key = keys[i], name = names[i];
      final boolean alpha = key.equals("backgroundColor");
      // (A swatch: click it for RuneLite's colour picker.)
      JLabel b = new JLabel();
      b.setOpaque(true);
      b.setBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR));
      b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
      b.setToolTipText("Click to change");
      b.addMouseListener(new MouseAdapter() {
        @Override public void mouseClicked(MouseEvent e) {
          RuneliteColorPicker p = pickers.create(WorldLagPanel.this, b.getBackground(), name + " colour", !alpha);
          p.setLocationRelativeTo(b);
          p.setOnColorChange(c -> set(key, c));
          p.setVisible(true);
        }
      });
      colours[i] = b;
      row(opts, name, b);
    }
    row(opts, "Good up to", goodMs);
    row(opts, "Bad above", badMs);
    row(opts, "Minutes", minutes);
    goodMs.setToolTipText("Input lag up to this many ms is good (green). Normal worlds measured 125-185.");
    badMs.setToolTipText("Input lag above this many ms is bad (red). World 404 measured 225-285.");
    minutes.setToolTipText("The input lag of the last this-many minutes of play.");
    goodMs.addChangeListener(e -> set("goodMs", goodMs.getValue()));
    badMs.addChangeListener(e -> set("badMs", badMs.getValue()));
    minutes.addChangeListener(e -> set("minutes", minutes.getValue()));
    add(fit(opts));
    JButton reset = new JButton("Reset to defaults");
    reset.setAlignmentX(Component.LEFT_ALIGNMENT);
    reset.addActionListener(e -> { for (String k : KEYS) configManager.unsetConfiguration(WorldLagConfig.GROUP, k); });
    add(Box.createVerticalStrut(4));
    add(reset);
    add(text("To move the box: hold Alt and drag it."));

    refreshOptions();
    refresh();
  }

  /** A row of the options: its name, then its control (62 px wide). */
  private int rows;
  private void row(JPanel p, String name, JComponent control) {
    GridBagConstraints c = new GridBagConstraints();
    c.gridy = rows++;
    c.insets = new Insets(2, 0, 2, 0);
    c.fill = GridBagConstraints.HORIZONTAL;
    if (name == null) { c.gridx = 0; c.gridwidth = 2; c.weightx = 1; p.add(control, c); return; }
    JLabel l = new JLabel(name);
    l.setForeground(ColorScheme.TEXT_COLOR);
    c.gridx = 0; c.weightx = 1;
    p.add(l, c);
    c.gridx = 1; c.weightx = 0;
    control.setPreferredSize(new Dimension(62, 22));
    // (Too narrow for both: the name gives way, never the control.)
    control.setMinimumSize(new Dimension(62, 22));
    l.setMinimumSize(new Dimension(0, 22));
    p.add(control, c);
  }
  /** A box never stretched taller than it needs (BoxLayout would). */
  private static final class Fit extends JPanel {
    Fit(LayoutManager l) { super(l); }
    @Override public Dimension getMaximumSize() { return new Dimension(Integer.MAX_VALUE, getPreferredSize().height); }
  }
  private static JComponent fit(JComponent c) {
    c.setAlignmentX(Component.LEFT_ALIGNMENT);
    return c;
  }

  private static JLabel heading(String s) {
    JLabel l = new JLabel(s);
    l.setFont(FontManager.getRunescapeBoldFont());
    l.setForeground(ColorScheme.BRAND_ORANGE);
    l.setAlignmentX(Component.LEFT_ALIGNMENT);
    l.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
    return l;
  }
  private static JLabel text(String s) {
    JLabel l = new JLabel("<html><body style='width: " + (PANEL_WIDTH - 62) + "px'>" + s + "</body></html>");
    l.setFont(FontManager.getRunescapeSmallFont());
    l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    l.setAlignmentX(Component.LEFT_ALIGNMENT);
    l.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
    return l;
  }
  private static JPanel card() {
    JPanel p = new Fit(null);
    p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
    p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    p.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
    p.setAlignmentX(Component.LEFT_ALIGNMENT);
    return p;
  }

  private void set(String key, Object value) {
    if (filling) return;
    configManager.setConfiguration(WorldLagConfig.GROUP, key, value);
  }

  /** The options as the config has them (after either place changed one). */
  void refreshOptions() {
    filling = true;
    try {
      showWorld.setSelected(config.showWorld());
      font.setSelectedItem(config.font());
      Supplier<?>[] c = {config::goodColor, config::okColor, config::badColor, config::textColor, config::backgroundColor};
      for (int i = 0; i < 5; i++) colours[i].setBackground((Color) c[i].get());
      goodMs.setValue(config.goodMs());
      badMs.setValue(config.badMs());
      minutes.setValue(config.minutes());
    } finally { filling = false; }
  }

  /** The numbers as of this tick (on Swing's thread). */
  void show(int world, int lag, int clicks, Map<Integer, Integer> seen) {
    nowWorld = world; nowLag = lag; nowClicks = clicks; nowSeen = seen;
    refresh();
  }
  void refresh() {
    int ms = nowLag;
    world.setText(nowWorld > 0 ? "World " + nowWorld : "Not logged in");
    lag.setText(ms < 0 ? "measuring" : ms + " ms");
    lag.setForeground(WorldLagOverlay.shade(config, ms));
    from.setText(nowClicks + " clicks timed, last " + config.minutes() + " min");
    session.removeAll();
    for (Map.Entry<Integer, Integer> e : nowSeen.entrySet()) {
      JLabel w = new JLabel("World " + e.getKey());
      w.setForeground(ColorScheme.TEXT_COLOR);
      JLabel v = new JLabel(e.getValue() + " ms", SwingConstants.RIGHT);
      v.setForeground(WorldLagOverlay.shade(config, e.getValue()));
      session.add(w); session.add(v);
    }
    if (nowSeen.isEmpty()) { JLabel none = new JLabel("No worlds measured yet"); none.setForeground(Color.GRAY); session.add(none); }
    session.revalidate();
    session.repaint();
  }
}

package com.worldlag;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.SwingUtilities;
import java.util.List;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

/**
 * World Lag: why a world feels bad. Only shows you numbers - it never types,
 * sends or changes anything.
 *
 * It times the clicks you already make whose result the server sends back:
 * a prayer (Activate / Deactivate: varp 83), gear (Wear / Wield / Equip: the
 * equipment, container 94) and food or a potion (Eat / Drink: the
 * inventory, 93). For each, how far into its tick you clicked and which
 * tick's update brought the change. The server's update brings its changes
 * first and then the tick (GameTick), so a change marks its click and the
 * next GameTick is the tick it came in. WorldLagStats has the sums; the box
 * (WorldLagOverlay) shows one number, the input lag.
 */
@PluginDescriptor(
    name = "World Lag",
    description = "Your input lag on this world: how long before the next tick a click has to go in to count",
    tags = {"lag", "ping", "tick", "world", "delay"})
public class WorldLagPlugin extends Plugin {
  private static final int PRAYER = 0, WORN = 1, INV = 2;
  private static final int PRAYER_VARP = 83, INVENTORY = 93, EQUIPMENT = 94;
  /** A click whose change hasn't come back after this many ticks is dropped
   *  (it did nothing: a full inventory, an eat delay). */
  private static final int GIVE_UP = 4;
  private static final Pattern PRAYERS = Pattern.compile(
      "Quick-prayers|Protect|Piety|Rigour|Augury|Eagle|Mystic|Smite|Redemption|Retribution|Chivalry|Preserve|Rapid|Steel|Ultimate|Incredible|Hawk|Thick|Burst|Superhuman|Clarity|Sharp|Improved|Deadeye|Vigour");

  @Inject private Client client;
  @Inject private WorldLagConfig config;
  @Inject private ConfigManager configManager;
  @Inject private OverlayManager overlayManager;
  @Inject private WorldLagOverlay overlay;
  @Inject private ClientToolbar clientToolbar;
  @Inject private ColorPickerManager colorPickerManager;

  final WorldLagStats stats = new WorldLagStats();
  /** Each world's input lag this session (its latest). */
  final Map<Integer, Integer> seen = new LinkedHashMap<>();
  private WorldLagPanel panel;
  private NavigationButton button;

  private static final class Pending {
    final int kind, tick;
    final double phase;
    final String target;
    final boolean timed;
    boolean back;
    Pending(int kind, int tick, double phase, String target, boolean timed) {
      this.kind = kind; this.tick = tick; this.phase = phase; this.target = target; this.timed = timed;
    }
  }
  private final List<Pending> pending = new ArrayList<>();
  /** GameTicks seen, and when the last came (ms, -1: none since a load). */
  private int ticks;
  private double lastTickAt = -1;
  /** The longest gap between client frames since the last tick (a stall of
   *  your PC's, not the world's). */
  private double lastFrameAt = -1, worstFrameGap;
  private int world = -1;

  @Provides
  WorldLagConfig provideConfig(ConfigManager m) {
    return m.getConfig(WorldLagConfig.class);
  }

  @Override
  protected void startUp() {
    overlayManager.add(overlay);
    panel = new WorldLagPanel(config, configManager, colorPickerManager);
    button = NavigationButton.builder().tooltip("World Lag").icon(icon()).priority(10).panel(panel).build();
    clientToolbar.addNavigation(button);
  }

  /** The side bar's icon: a stopwatch. */
  private static BufferedImage icon() {
    BufferedImage im = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = im.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    g.setColor(new Color(0xdc8a00));
    g.setStroke(new BasicStroke(1.6f));
    g.drawOval(2, 3, 12, 12);
    g.fillRect(6, 0, 4, 2);
    g.drawLine(8, 9, 8, 5);
    g.drawLine(8, 9, 11, 9);
    g.dispose();
    return im;
  }

  @Override
  protected void shutDown() {
    overlayManager.remove(overlay);
    clientToolbar.removeNavigation(button);
    reset();
    seen.clear();
  }

  private static double now() { return System.nanoTime() / 1e6; }

  private void reset() {
    stats.clear();
    pending.clear();
    lastTickAt = -1;
  }

  int world() { return world; }

  // --- The clicks, the changes they make, the ticks. ---
  @Subscribe
  public void onMenuOptionClicked(MenuOptionClicked e) {
    String op = e.getMenuOption();
    int kind;
    if ("Activate".equals(op) || "Deactivate".equals(op)) {
      if (!PRAYERS.matcher(Text.removeTags(e.getMenuTarget())).find()) return;
      kind = PRAYER;
    }
    else if ("Wear".equals(op) || "Wield".equals(op) || "Equip".equals(op)) kind = WORN;
    else if ("Eat".equals(op) || "Drink".equals(op)) kind = INV;
    else return;
    if (lastTickAt < 0) return;
    String target = Text.removeTags(e.getMenuTarget());
    // Timed: only the first of its kind in a tick (it decides the tick the
    // change comes in); a prayer turned on and off in one tick (a flick)
    // changes nothing, so neither is timed.
    boolean timed = true;
    for (Pending p : pending) {
      if (p.kind != kind || p.tick != ticks) continue;
      timed = false;
      if (kind == PRAYER && p.target.equals(target)) { pending.remove(p); break; }
    }
    pending.add(new Pending(kind, ticks, now() - lastTickAt, target, timed));
  }

  private void changed(int kind) {
    for (Pending p : pending) if (p.kind == kind) p.back = true;
  }
  @Subscribe
  public void onVarbitChanged(VarbitChanged e) {
    if (e.getVarpId() == PRAYER_VARP) changed(PRAYER);
  }
  @Subscribe
  public void onItemContainerChanged(ItemContainerChanged e) {
    if (e.getContainerId() == EQUIPMENT) changed(WORN);
    else if (e.getContainerId() == INVENTORY) changed(INV);
  }

  @Subscribe
  public void onClientTick(ClientTick e) {
    double t = now();
    if (lastFrameAt > 0) worstFrameGap = Math.max(worstFrameGap, t - lastFrameAt);
    lastFrameAt = t;
  }

  @Subscribe
  public void onGameTick(GameTick e) {
    double t = now();
    if (client.getWorld() != world) { reset(); world = client.getWorld(); }
    if (lastTickAt > 0 && t - lastTickAt < 5000) stats.addTickGap(t, t - lastTickAt, worstFrameGap > 100);
    lastTickAt = t;
    worstFrameGap = 0;
    ticks++;
    for (Iterator<Pending> it = pending.iterator(); it.hasNext(); ) {
      Pending p = it.next();
      int n = ticks - p.tick;
      if (p.back) { if (p.timed) stats.addClick(t, p.phase, n); it.remove(); }
      else if (n > GIVE_UP) it.remove();
    }
    stats.trim(t, config.minutes() * 60_000.0);
    int lag = stats.deadlineMs();
    if (lag >= 0) { seen.remove(world); seen.put(world, lag); }
    if (panel != null) {
      final int w = world, n = stats.clickCount();
      final Map<Integer, Integer> copy = new LinkedHashMap<>(seen);
      SwingUtilities.invokeLater(() -> panel.show(w, lag, n, copy));
    }
  }

  @Subscribe
  public void onConfigChanged(ConfigChanged e) {
    if (WorldLagConfig.GROUP.equals(e.getGroup()) && panel != null) SwingUtilities.invokeLater(() -> { panel.refreshOptions(); panel.refresh(); });
  }

  @Subscribe
  public void onGameStateChanged(GameStateChanged e) {
    // (A load or a hop: the next tick's gap isn't the world's.)
    if (e.getGameState() != GameState.LOGGED_IN) { lastTickAt = -1; pending.clear(); }
  }
}

package com.worldlag;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * World Lag's numbers over the last few minutes (no RuneLite in here, so it
 * can be tested on its own):
 *  - the click deadline: how long before the next tick shows a click has to
 *    be made to make it. Each timed click is how far into its tick it was
 *    made (ms after that tick arrived) and how many ticks later its change
 *    came back (1 = the next). The deadline's point in the tick is where
 *    "made it" turns into "missed": the cut that the fewest clicks disagree
 *    with. Needs a few misses near it before it's trusted;
 *  - late clicks: clicks made well before the deadline (150+ ms) that still
 *    came back a tick or more late;
 *  - late ticks: ticks arriving 700+ ms after the one before - the ones
 *    during a frame stall of your own PC counted apart.
 * Measured on recorded raids: world 404 250 ms / 9.5% / 1.5%, worlds
 * 416 / 618 / 487 125-150 ms / ~2% / 0.3%.
 */
final class WorldLagStats {
  static final double TICK_MS = 600;
  static final double LATE_TICK_MS = 700;
  /** Clicks this far before the deadline count toward late clicks. */
  static final double CLEAR_MS = 150;
  static final int MIN_CLICKS = 30;
  static final int MIN_MISSES = 5;

  private static final class Click {
    final double at, phase;
    final int ticks;
    Click(double at, double phase, int ticks) { this.at = at; this.phase = phase; this.ticks = ticks; }
  }
  private static final class Gap {
    final double at, ms;
    final boolean pcStall;
    Gap(double at, double ms, boolean pcStall) { this.at = at; this.ms = ms; this.pcStall = pcStall; }
  }

  private final Deque<Click> clicks = new ArrayDeque<>();
  private final Deque<Gap> gaps = new ArrayDeque<>();

  void addClick(double at, double phaseMs, int ticks) { clicks.addLast(new Click(at, phaseMs, ticks)); }
  void addTickGap(double at, double gapMs, boolean pcStall) { gaps.addLast(new Gap(at, gapMs, pcStall)); }

  /** Forget what's older than the window. */
  void trim(double now, double windowMs) {
    while (!clicks.isEmpty() && clicks.peekFirst().at < now - windowMs) clicks.removeFirst();
    while (!gaps.isEmpty() && gaps.peekFirst().at < now - windowMs) gaps.removeFirst();
  }
  void clear() { clicks.clear(); gaps.clear(); }

  int clickCount() { return clicks.size(); }
  int tickCount() { return gaps.size(); }

  /** Where in the tick clicks stop making the next one (ms after it
   *  arrived), or -1: not enough yet. */
  double cutoffPhase() {
    if (clicks.size() < MIN_CLICKS) return -1;
    int best = Integer.MAX_VALUE, lo = 0, hi = 0;
    for (int t = 0; t <= 600; t += 10) {
      int err = 0;
      for (Click c : clicks) if ((c.phase < t) != (c.ticks == 1)) err++;
      if (err < best) { best = err; lo = t; hi = t; }
      else if (err == best) hi = t;
    }
    double cut = (lo + hi) / 2.0;
    // (Trusted only with misses near it: clicks made after it that missed.)
    int misses = 0;
    for (Click c : clicks) if (c.phase >= cut && c.phase < cut + 200 && c.ticks > 1) misses++;
    return misses >= MIN_MISSES ? cut : -1;
  }

  /** The click deadline, ms before the next tick shows; -1: not enough yet. */
  int deadlineMs() {
    double cut = cutoffPhase();
    return cut < 0 ? -1 : (int) Math.round(TICK_MS - cut);
  }

  /** Late clicks, %: made clear of the deadline, still a tick or more late
   *  (-1: none to judge by). */
  double lateClickPct() {
    double cut = cutoffPhase();
    double clear = cut < 0 ? 200 : cut - CLEAR_MS;
    int n = 0, late = 0;
    for (Click c : clicks) if (c.phase < clear) { n++; if (c.ticks > 1) late++; }
    return n < 10 ? -1 : 100.0 * late / n;
  }

  /** Late ticks, % of ticks: the world's (pc = false) or during your own
   *  PC's frame stalls (pc = true). */
  double lateTickPct(boolean pc) {
    if (gaps.isEmpty()) return 0;
    int late = 0;
    for (Gap g : gaps) if (g.ms >= LATE_TICK_MS && g.pcStall == pc) late++;
    return 100.0 * late / gaps.size();
  }
}

